  t.plan(3)

  const fastify = require('../../')()

  t.after(() => fastify.close())

  fastify.get('/headers', function (req, reply) {
    reply.header('x-foo', 'foo')
    t.assert.strictEqual(reply.getHeader('x-foo'), 'foo')

    t.assert.strictEqual(reply.removeHeader('x-foo'), reply)
